//! The embedded built-in configs and the config YAML reader and writer against OCIO's
//! (`OCIOYaml.cpp`, `BuiltinConfigRegistry.cpp`), on every built-in config OCIO ships (ACES CG /
//! Studio, each release), the Studio all-views config this crate also embeds, and
//! `every_key.ocio` (every key OCIO's reader knows, non-default values, every transform type).
//! References from PyOpenColorIO 2.5.1, regenerated by `tests/data/gen_ocio_configs.py` (which
//! also rewrites the embedded `src/builtin/data/*.ocio` from PyOpenColorIO):
//!
//! - the registry: names, order, UI names, recommended/default flags, and the text of each
//!   embedded config (length and FNV-1a hash) equal PyOpenColorIO's; `ocio://` URIs resolve and
//!   load as in OCIO;
//! - every CG config is a subset of the Studio config of the same release (colour spaces,
//!   roles, displays/views, named transforms, view transforms, looks: same names, same
//!   definitions);
//! - the pixels: every colour space to and from the reference, every display/view from the
//!   scene-linear role, every named transform both ways, on three probes;
//! - the text: `Config::serialize` parses to the same YAML tree as PyOpenColorIO's own
//!   `serialize` of the same config (tags, keys in order, values; numbers to float precision).
//!   A key this writer invents, or one it drops, fails here.

use saphyr::{LoadableYamlNode, Scalar, Yaml};
use std::path::Path;
use vfx_ocio::builtin::embedded;
use vfx_ocio::{Config, Transform, TransformDirection};

fn data(name: &str) -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/data")
        .join(name)
}

fn reference() -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(data("ocio_configs_pyocio.json")).unwrap())
        .unwrap()
}

/// A reference config: an embedded one (`"builtin"`) or a fixture file (`"file"`), with a label.
fn load(cfg: &serde_json::Value) -> (String, Config) {
    if let Some(name) = cfg["builtin"].as_str() {
        let config = embedded::get(name).unwrap_or_else(|| panic!("{name} is not embedded"));
        (name.to_string(), config)
    } else {
        let file = cfg["file"].as_str().unwrap();
        let config = Config::from_file(data("ocio_configs").join(file))
            .unwrap_or_else(|e| panic!("{file}: {e}"));
        (file.to_string(), config)
    }
}

/// PyOpenColorIO's `serialize` of a reference config: its fixture, or (null) the embedded text
/// itself when OCIO's text already is its own serialize.
fn pyocio_serialize(cfg: &serde_json::Value) -> String {
    match cfg["pyocio_serialize"].as_str() {
        Some(f) => std::fs::read_to_string(data("ocio_configs").join(f)).unwrap(),
        None => embedded::find(cfg["builtin"].as_str().unwrap())
            .unwrap()
            .yaml
            .to_string(),
    }
}

fn fnv1a64(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in bytes {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    format!("{h:016x}")
}

/// The embedded configs are OCIO's registry: same names, order, UI names, flags and text.
#[test]
fn builtin_registry_matches_pyocio() {
    let reference = reference();
    let want = reference["builtin_registry"].as_array().unwrap();
    let ours = embedded::ocio_builtins();
    assert_eq!(ours.len(), want.len(), "number of built-in configs");
    for (e, w) in ours.iter().zip(want) {
        assert_eq!(e.name, w["name"].as_str().unwrap());
        assert_eq!(e.ui_name, w["ui_name"].as_str().unwrap(), "{}", e.name);
        assert_eq!(
            e.recommended,
            w["recommended"].as_bool().unwrap(),
            "{}",
            e.name
        );
        assert_eq!(
            e.name == embedded::DEFAULT_BUILTIN_CONFIG,
            w["default"].as_bool().unwrap(),
            "{}: default",
            e.name
        );
        assert_eq!(
            e.yaml.len() as u64,
            w["len"].as_u64().unwrap(),
            "{}: text length",
            e.name
        );
        assert_eq!(
            fnv1a64(e.yaml.as_bytes()),
            w["fnv1a64"].as_str().unwrap(),
            "{}: the embedded text is not PyOpenColorIO's; rerun tests/data/gen_ocio_configs.py",
            e.name
        );
        assert!(e.ocio_builtin);
    }
}

/// `ResolveConfigPath` and `CreateFromFile("ocio://...")` as in OCIO.
#[test]
fn ocio_uris_resolve_and_load_like_ocio() {
    let reference = reference();
    for pair in reference["resolve_config_path"].as_array().unwrap() {
        let (uri, want) = (pair[0].as_str().unwrap(), pair[1].as_str().unwrap());
        assert_eq!(Config::resolve_config_path(uri).unwrap(), want, "{uri}");
        let Some(name) = embedded::uri_name(want) else {
            continue;
        };
        match embedded::ocio_builtins().iter().find(|e| e.name == name) {
            Some(e) => {
                let cfg = Config::from_file(uri).unwrap_or_else(|err| panic!("{uri}: {err}"));
                assert_eq!(cfg.name(), e.name, "{uri}");
                assert_eq!(
                    Config::create_from_builtin_config(uri).unwrap().name(),
                    e.name
                );
            }
            None => {
                let err = Config::from_file(uri).unwrap_err().to_string();
                assert_eq!(
                    err,
                    format!("Could not find '{name}' in the built-in configurations.")
                );
            }
        }
    }
    // A name without the prefix, any case, as `CreateFromBuiltinConfig` takes it.
    for name in [
        "default",
        "CG-CONFIG-LATEST",
        "studio-config-v1.0.0_aces-v1.3_ocio-v2.1",
    ] {
        Config::create_from_builtin_config(name).unwrap_or_else(|e| panic!("{name}: {e}"));
    }
    // The all-views config is ours, not OCIO's.
    assert!(Config::from_file(format!("ocio://{}", embedded::STUDIO_ALL_VIEWS)).is_err());
}

/// Every CG config is a subset of the Studio config of the same release: each colour space,
/// role, display/view, named transform, view transform and look the CG config has, the Studio
/// config has with the same definition. PyOpenColorIO says so too (the generator asserts it and
/// records what the CG config defines; this port must parse the same lists).
#[test]
fn cg_configs_are_subsets_of_studio() {
    let reference = reference();
    let subsets = reference["cg_subset"].as_array().unwrap();
    assert_eq!(
        subsets.len(),
        embedded::ocio_builtins()
            .iter()
            .filter(|e| e.is_cg())
            .count()
    );
    let strs = |v: &serde_json::Value| -> Vec<String> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|s| s.as_str().unwrap().to_string())
            .collect()
    };
    for s in subsets {
        let cg_entry = embedded::find(s["cg"].as_str().unwrap()).unwrap();
        let studio_entry = cg_entry.studio_twin().unwrap();
        assert_eq!(studio_entry.name, s["studio"].as_str().unwrap());
        let (cg, studio) = (cg_entry.config(), studio_entry.config());
        let tag = cg_entry.name;

        let names: Vec<String> = cg
            .colorspaces()
            .iter()
            .map(|c| c.name().to_string())
            .collect();
        assert_eq!(names, strs(&s["colorspaces"]), "{tag}: colour spaces");
        for c in cg.colorspaces() {
            let other = studio
                .colorspace(c.name())
                .unwrap_or_else(|| panic!("{tag}: {}", c.name()));
            assert_eq!(
                format!("{other:?}"),
                format!("{c:?}"),
                "{tag}: colour space {}",
                c.name()
            );
        }

        for role in s["roles"].as_array().unwrap() {
            let (r, cs) = (role[0].as_str().unwrap(), role[1].as_str().unwrap());
            assert_eq!(cg.roles().get(r), Some(cs), "{tag}: role {r}");
            assert_eq!(studio.roles().get(r), Some(cs), "{tag}: studio role {r}");
        }
        assert_eq!(
            cg.roles().iter().count(),
            s["roles"].as_array().unwrap().len(),
            "{tag}: roles"
        );

        let displays = s["displays"].as_array().unwrap();
        assert_eq!(
            cg.displays().displays().len(),
            displays.len(),
            "{tag}: displays"
        );
        for d in displays {
            let display = d["display"].as_str().unwrap();
            let views = cg.get_views(display);
            let names: Vec<String> = views.iter().map(|v| v.name().to_string()).collect();
            assert_eq!(names, strs(&d["views"]), "{tag}: views of {display}");
            let theirs = studio.get_views(display);
            for v in views {
                let other = theirs
                    .iter()
                    .find(|o| o.name() == v.name())
                    .unwrap_or_else(|| panic!("{tag}: {display} / {} not in studio", v.name()));
                assert_eq!(
                    format!("{other:?}"),
                    format!("{v:?}"),
                    "{tag}: {display} / {}",
                    v.name()
                );
            }
            assert_eq!(
                cg.default_view(display),
                studio.default_view(display),
                "{tag}: default view of {display}"
            );
        }

        let nts: Vec<String> = cg
            .named_transforms()
            .iter()
            .map(|n| n.name.clone())
            .collect();
        assert_eq!(nts, strs(&s["named_transforms"]), "{tag}: named transforms");
        for nt in cg.named_transforms() {
            let other = studio.named_transform(&nt.name).unwrap();
            assert_eq!(
                format!("{other:?}"),
                format!("{nt:?}"),
                "{tag}: named transform {}",
                nt.name
            );
        }
        for vt in cg.view_transforms() {
            let other = studio.view_transform(vt.name()).unwrap();
            assert_eq!(
                format!("{other:?}"),
                format!("{vt:?}"),
                "{tag}: view transform {}",
                vt.name()
            );
        }
        for look in cg.looks().all() {
            let other = studio.looks().get(look.name()).unwrap();
            assert_eq!(
                format!("{other:?}"),
                format!("{look:?}"),
                "{tag}: look {}",
                look.name()
            );
        }
    }
}

/// Each colour space's aliases and interop ID as PyOpenColorIO reads them.
#[test]
fn builtin_colorspace_names_match_pyocio() {
    let reference = reference();
    for cfg in reference["configs"].as_array().unwrap() {
        let (label, config) = load(cfg);
        for cs in cfg["colorspaces"].as_array().unwrap() {
            let name = cs["name"].as_str().unwrap();
            let ours = config
                .colorspace(name)
                .unwrap_or_else(|| panic!("{label}: {name}"));
            let aliases: Vec<&str> = cs["aliases"]
                .as_array()
                .unwrap()
                .iter()
                .map(|a| a.as_str().unwrap())
                .collect();
            assert_eq!(
                ours.aliases(),
                aliases.as_slice(),
                "{label}: {name} aliases"
            );
            assert_eq!(
                ours.interop_id(),
                cs["interop_id"].as_str().unwrap(),
                "{label}: {name}"
            );
        }
    }
}

fn probes(v: &serde_json::Value) -> Vec<[f32; 3]> {
    v["probes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| {
            let p = p.as_array().unwrap();
            [
                p[0].as_f64().unwrap() as f32,
                p[1].as_f64().unwrap() as f32,
                p[2].as_f64().unwrap() as f32,
            ]
        })
        .collect()
}

fn close(got: f32, want: f32, display: bool) -> bool {
    (got.is_nan() && want.is_nan())
        || (got - want).abs() <= 2e-4 * want.abs().max(1.0)
        // A display encoding (gamma 2.2 / 2.6, PQ) amplifies float noise at zero: a linear
        // 1e-8 encodes to ~2e-4 (2.2) or ~1e-3 (PQ). OCIO lands on exactly 0 there.
        || (display && want.abs() < 1e-5 && got.abs() < 1.2e-3)
}

/// Every conversion PyOpenColorIO makes, made here from the same config file.
#[test]
fn builtin_configs_convert_as_pyocio() {
    let reference = reference();
    let probes = probes(&reference);
    let mut bad = Vec::new();
    let mut checked = 0usize;

    for cfg in reference["configs"].as_array().unwrap() {
        let (file, config) = load(cfg);
        for row in cfg["rows"].as_array().unwrap() {
            let what = format!("{file}: {row}");
            let what = what.split(", \"out\"").next().unwrap().to_string();
            let proc = if let Some(nt) = row["named"].as_str() {
                let nt = config.named_transform(nt).unwrap();
                let forward = row["direction"] == "forward";
                let (t, dir) = match (forward, &nt.forward, &nt.inverse) {
                    (true, Some(f), _) => (f.clone(), TransformDirection::Forward),
                    (true, None, Some(i)) => (i.clone(), TransformDirection::Inverse),
                    (false, _, Some(i)) => (i.clone(), TransformDirection::Forward),
                    (false, Some(f), None) => (f.clone(), TransformDirection::Inverse),
                    _ => (Transform::group(vec![]), TransformDirection::Forward),
                };
                config.processor_from_transform(&t, dir)
            } else if let Some(display) = row["display"].as_str() {
                config.display_processor(
                    row["src"].as_str().unwrap(),
                    display,
                    row["view"].as_str().unwrap(),
                )
            } else {
                config.processor(row["src"].as_str().unwrap(), row["dst"].as_str().unwrap())
            };
            let Some(want) = row["out"].as_array() else {
                if proc.is_ok() {
                    bad.push(format!(
                        "{what}: PyOCIO fails ({}), this port builds it",
                        row["error"]
                    ));
                }
                continue;
            };
            let proc = match proc {
                Ok(p) => p,
                Err(e) => {
                    bad.push(format!("{what}: {e}"));
                    continue;
                }
            };
            let display = row["display"].is_string();
            let mut px = probes.clone();
            proc.apply_rgb(&mut px);
            checked += 1;
            for (got, want) in px.iter().zip(want) {
                let want: Vec<f32> = want
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_f64().unwrap() as f32)
                    .collect();
                if (0..3).any(|c| !close(got[c], want[c], display)) {
                    bad.push(format!("{what}: got {got:?}, PyOCIO {want:?}"));
                    break;
                }
            }
        }
    }
    assert!(
        bad.is_empty(),
        "{} of {checked} conversions differ:\n{}",
        bad.len(),
        bad.join("\n")
    );
    // Every conversion builds, ADX10 / ADX16 from ACES2065-1 in the five studio configs included
    // (the half-domain Lut1D inverse, B31; they were refused before).
    assert!(checked > 1000, "{checked}");
}

/// A scalar's text, or a number.
enum Leaf {
    Num(f64),
    Text(String),
}

fn leaf(y: &Yaml) -> Option<Leaf> {
    Some(match y {
        Yaml::Value(Scalar::Integer(i)) => Leaf::Num(*i as f64),
        Yaml::Value(Scalar::FloatingPoint(f)) => Leaf::Num(f.into_inner()),
        Yaml::Value(Scalar::Boolean(b)) => Leaf::Text(b.to_string()),
        Yaml::Value(Scalar::Null) => Leaf::Text("~".into()),
        Yaml::Value(Scalar::String(s)) => Leaf::Text(s.trim_end_matches('\n').to_string()),
        Yaml::Representation(s, _, _) => match s.parse::<f64>() {
            Ok(n) => Leaf::Num(n),
            Err(_) => Leaf::Text(s.trim_end_matches('\n').to_string()),
        },
        _ => return None,
    })
}

/// Tree equality: tags, mapping keys in order, sequences, scalars (numbers to float precision).
fn same(path: &str, a: &Yaml, b: &Yaml, diffs: &mut Vec<String>) {
    match (a, b) {
        (Yaml::Tagged(ta, ia), Yaml::Tagged(tb, ib)) => {
            if ta.suffix != tb.suffix {
                diffs.push(format!("{path}: tag !<{}> vs !<{}>", ta.suffix, tb.suffix));
            } else {
                same(&format!("{path}!<{}>", ta.suffix), ia, ib, diffs);
            }
        }
        (Yaml::Mapping(ma), Yaml::Mapping(mb)) => {
            let key = |k: &Yaml| match leaf(k) {
                Some(Leaf::Text(t)) => t,
                Some(Leaf::Num(n)) => n.to_string(),
                None => format!("{k:?}"),
            };
            let names_a: Vec<String> = ma.keys().map(key).collect();
            let names_b: Vec<String> = mb.keys().map(key).collect();
            if names_a != names_b {
                diffs.push(format!("{path}: keys {names_a:?} vs {names_b:?}"));
                return;
            }
            for ((k, va), (_, vb)) in ma.iter().zip(mb.iter()) {
                same(&format!("{path}.{}", key(k)), va, vb, diffs);
            }
        }
        (Yaml::Sequence(sa), Yaml::Sequence(sb)) => {
            if sa.len() != sb.len() {
                diffs.push(format!("{path}: {} vs {} items", sa.len(), sb.len()));
                return;
            }
            for (i, (x, y)) in sa.iter().zip(sb).enumerate() {
                same(&format!("{path}[{i}]"), x, y, diffs);
            }
        }
        _ => match (leaf(a), leaf(b)) {
            (Some(Leaf::Num(x)), Some(Leaf::Num(y))) => {
                if (x - y).abs() > 1e-6 * x.abs().max(y.abs()).max(1e-30) {
                    diffs.push(format!("{path}: {x} vs {y}"));
                }
            }
            (Some(Leaf::Text(x)), Some(Leaf::Text(y))) if x == y => {}
            _ => diffs.push(format!("{path}: {a:?} vs {b:?}")),
        },
    }
}

/// `serialize` writes what OCIO writes: the same YAML tree as PyOpenColorIO's `serialize`.
#[test]
fn serialize_matches_pyocio_serialize() {
    let reference = reference();
    let mut report = Vec::new();
    for cfg in reference["configs"].as_array().unwrap() {
        let (file, config) = load(cfg);
        let ours = config.serialize().unwrap_or_else(|e| panic!("{file}: {e}"));
        let theirs = pyocio_serialize(cfg);
        let a = Yaml::load_from_str(&ours)
            .unwrap_or_else(|e| panic!("{file}: ours does not parse: {e}\n{ours}"));
        let b = Yaml::load_from_str(&theirs).unwrap();
        let mut diffs = Vec::new();
        same("", &a[0], &b[0], &mut diffs);
        if !diffs.is_empty() {
            report.push(format!(
                "{file} ({} differences):\n  {}",
                diffs.len(),
                diffs
                    .iter()
                    .take(40)
                    .cloned()
                    .collect::<Vec<_>>()
                    .join("\n  ")
            ));
        }
        // And it reads back to the same config.
        Config::from_yaml_str(&ours, data("ocio_configs"))
            .unwrap_or_else(|e| panic!("{file}: reload: {e}"));
    }
    assert!(report.is_empty(), "{}", report.join("\n"));
}

/// With `VFX_OCIO_DUMP_DIR` set, writes this port's serialization of every embedded config and
/// every fixture there, for
/// `tests/data/check_serialize_in_pyocio.py` (PyOpenColorIO must load it, validate it, build the
/// same processors, and re-serialize it to the same text as the original). A no-op otherwise.
#[test]
fn dump_serialized_for_pyocio() {
    let Some(out) = std::env::var_os("VFX_OCIO_DUMP_DIR") else {
        return;
    };
    let out = std::path::PathBuf::from(out);
    std::fs::create_dir_all(&out).unwrap();
    for e in embedded::entries() {
        let path = out.join(format!("{}.ocio", e.name));
        std::fs::write(path, e.config().serialize().unwrap()).unwrap();
    }
    for e in std::fs::read_dir(data("ocio_configs")).unwrap() {
        let p = e.unwrap().path();
        if p.extension().is_some_and(|e| e == "ocio") {
            let c = Config::from_file(&p).unwrap();
            std::fs::write(out.join(p.file_name().unwrap()), c.serialize().unwrap()).unwrap();
        }
    }
}
